import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Switch from 'flarum/common/components/Switch';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import sortTags from 'ext:flarum/tags/common/utils/sortTags';
export default class PromptTagsListSetting extends Component {
  loading = true;
  oninit(vnode) {
    super.oninit(vnode);

    // Only the primary tags are loaded by default, so we need to make the same
    // request the tags page settings does to load the full list
    app.store.find('tags', {
      include: 'parent'
    }).then(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    if (this.loading) {
      return m(LoadingIndicator, null);
    }
    return sortTags(app.store.all('tags')).map(tag => m("div", {
      className: "Form-group"
    }, m(Switch, {
      state: this.tagIds().includes(tag.id()),
      onchange: value => this.toggle(tag, value)
    }, tag.name())));
  }
  tagIds() {
    let tagIds;
    try {
      tagIds = JSON.parse(this.attrs.setting() || '[]');
    } catch (e) {
      tagIds = [];
    }
    return Array.isArray(tagIds) ? tagIds : [];
  }
  toggle(tag, value) {
    const tagIds = this.tagIds();
    this.attrs.setting(JSON.stringify(value ? [...tagIds, tag.id()] : tagIds.filter(id => id !== tag.id())));
  }
}
flarum.reg.add('framio-community', 'follow-tags/admin/components/PromptTagsListSetting', PromptTagsListSetting);