import app from 'flarum/admin/app';
import Extend from 'flarum/common/extenders';
export default [new Extend.Admin('framio-community:default-group') //
.setting(() => {
  const groups = app.store.all('groups').filter(g => g.id() !== '2');
  const options = {};
  groups.forEach(g => {
    options[g.id()] = g.namePlural();
  });
  return {
    setting: 'fof-default-group.group',
    type: 'select',
    label: app.translator.trans('fof-default-group.admin.settings.label'),
    help: app.translator.trans('fof-default-group.admin.settings.info'),
    default: '3',
    // Member group
    options
  };
})];